const out = [];

for (const item of $input.all()) {
  const r = item.json;

  if (!r?.id) continue;

  if (r.unload_log === true) {
    out.push({
      json: {
        record_id: r.id,
        action: 'log'
      }
    });
  }

  if (r.update_interim === true) {
    out.push({
      json: {
        record_id: r.id,
        action: 'interim'
      }
    });
  }

  if (r.update_characteristic === true) {
    out.push({
      json: {
        record_id: r.id,
        action: 'characteristic'
      }
    });
  }
}

return out;

let messages = $json.messages ?? [];

if (typeof messages === 'string') {
  try {
    messages = JSON.parse(messages);
  } catch {
    messages = [];
  }
}

if (!Array.isArray(messages) || messages.length === 0) {
  throw new Error('В agent_v3.messages нет текстовых сообщений этого диалога');
}

const dialog = $('Get V3 Dialog').item.json;
const task = $('Get V3 Task').item.json;
const request = $('Expand Checked Actions').item.json;

const personName = String(
  dialog.person_name ||
  dialog.telegram_username ||
  'Собеседник'
).trim();

const assistantName = String(
  task.assistant_identity ||
  task.assistant_role ||
  'Ассистент'
).split('\n')[0].trim() || 'Ассистент';

let zone = task.timezone || 'Europe/Moscow';
if (zone && typeof zone === 'object') {
  zone = zone.name || 'Europe/Moscow';
}
zone = String(zone || 'Europe/Moscow');

function fmt(value) {
  if (!value) return '';
  const d = new Date(value);
  if (!Number.isFinite(d.getTime())) return '';

  try {
    return new Intl.DateTimeFormat('ru-RU', {
      timeZone: zone,
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    }).format(d);
  } catch {
    return d.toISOString();
  }
}

const parts = [];

for (const row of messages) {
  const text = String(row?.text ?? '').trim();
  if (!text) continue;

  let speaker = assistantName;

  if (String(row.direction || '').toLowerCase() === 'inbound') {
    speaker = personName;
  } else if (String(row.sender_type || '').toLowerCase() === 'owner') {
    speaker = 'Администратор';
  }

  const date = fmt(row.message_at);
  const title = date ? `[${date}] ${speaker}:` : `${speaker}:`;
  parts.push(`${title}\n${text}`);
}

if (!parts.length) {
  throw new Error('Сообщения найдены, но итоговый текст диалога пуст');
}

const dialogText = parts.join(
  '\n\n----------------------------------------\n\n'
);

const LOG_LIMIT = 95000;
let airtableLog = dialogText;
let logTruncated = false;

if (airtableLog.length > LOG_LIMIT) {
  logTruncated = true;
  airtableLog =
    '[ВНИМАНИЕ: начало очень длинного диалога не помещается в поле Airtable. ' +
    'Ниже сохранены последние сообщения.]\n\n' +
    airtableLog.slice(-(LOG_LIMIT - 180));
}

return {
  json: {
    record_id: request.record_id,
    action: request.action,
    dialog_name: dialog.Dialog || request.record_id,
    person_name: personName,
    person_role: dialog.person_role || '',
    dialog_status:
      (dialog.Status && typeof dialog.Status === 'object')
        ? (dialog.Status.name || '')
        : (dialog.Status || ''),
    task_name: task.Name_task || '',
    goal: task.goal || '',
    required_result: task.required_result || '',
    assistant_role: task.assistant_role || '',
    communication_style: task.communication_style || '',
    messages_count: parts.length,
    dialog_text: dialogText,
    airtable_log: airtableLog,
    log_truncated: logTruncated
  }
};
